const envTopic = $env.CLOUDLESS_CAROUSEL_TOPIC;
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const numSlides = Number(body.num_slides || $env.CLOUDLESS_CAROUSEL_SLIDES || 7);
const publish = body.publish === false ? false : true;
const waitForPublish = body.wait_for_publish === true;
const accountId = body.target_account_id
  || $env.CLOUDLESS_LINKEDIN_ORG_ACCOUNT_ID
  || '9c4451bb-e820-489f-8676-76ddbc788ffe';
return [{
  json: {
    // Explicit override only — the fresh-topic pick happens in
    // "Pick Fresh Topic" after fetching recent published posts.
    topic_override: body.topic || envTopic || null,
    num_slides: Math.max(3, Math.min(10, numSlides || 7)),
    publish,
    wait_for_publish: waitForPublish,
    target_account_id: accountId,
    tone: body.tone || 'clear and friendly',
    brand: 'cloudless.gr',
    pipeline: 'cf-txt2img-img2img-nlp-spellcheck-seo',
  }
}];

const cfg = $('Resolve Cloudless Config').item.json;
const raw = $json;
const ok = !!(raw && raw.post_id);
return [{
  json: {
    ok,
    brand: 'cloudless.gr',
    account: (raw.target_account && raw.target_account.display_name) || 'cloudless.gr',
    account_type: (raw.target_account && raw.target_account.account_type) || 'organization',
    post_id: raw.post_id || null,
    status: raw.status || (ok ? 'queued' : 'failed'),
    platform_url: raw.platform_url || null,
    media_count: Array.isArray(raw.media_ids) ? raw.media_ids.length : 0,
    topic: ($('Pick Fresh Topic') && $('Pick Fresh Topic').item.json.topic) || cfg.topic_override || cfg.topic,
    num_slides: cfg.num_slides,
    publish: cfg.publish,
    pipeline: cfg.pipeline,
    nlp_fixed: !!(raw.nlp_report && raw.nlp_report.fixed),
    queue_warning: raw.queue_warning || null,
    error: ok ? null : (raw.message || raw.detail || raw.error || 'pipeline_failed'),
  }
}];

const crypto = require('crypto');
const secret = ($env.SOCIAL_TOTP_SECRET || '').trim().replace(/\s+/g, '').toUpperCase();
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const clean = secret.replace(/=+$/, '');
let bits = 0, value = 0;
const bytes = [];
for (const ch of clean) {
  const idx = ALPHABET.indexOf(ch);
  if (idx === -1) throw new Error('Invalid base32 char in SOCIAL_TOTP_SECRET');
  value = (value << 5) | idx;
  bits += 5;
  if (bits >= 8) { bytes.push((value >>> (bits - 8)) & 0xff); bits -= 8; }
}
const key = Buffer.from(bytes);
const msg = Buffer.alloc(8);
msg.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
const digest = crypto.createHmac('sha1', key).update(msg).digest();
const offset = digest[digest.length - 1] & 0x0f;
const otp = ((digest.readUInt32BE(offset) & 0x7fffffff) % 1000000).toString().padStart(6, '0');
return [{ json: { otp } }];

const cfg = $('Resolve Cloudless Config').item.json;
const access_token = $('Login Social API').item.json.access_token || null;
const raw = $input.first().json;
const posts = Array.isArray(raw.posts) ? raw.posts : (Array.isArray(raw) ? raw : []);

// Topic pool — 24 genuinely different angles (~48-day rotation at the
// every-2-days cadence, comfortably outside the 30-day dedup window).
const topics = [
  'How cloudless.gr helps teams ship serverless apps without managing servers',
  'Clear skies for your stack: Cloudflare Workers with cloudless.gr',
  'Stop babysitting servers — ship on the edge with cloudless.gr',
  'From idea to production on Cloudflare, guided by cloudless.gr',
  'Plain-English cloud: what cloudless.gr builds for Greek and EU teams',
  'Workers, R2, and AI on Cloudflare — without the ops headache (cloudless.gr)',
  'A practical path to serverless for SMEs with cloudless.gr',
  'Cut your cloud bill: fixed-scope Cloudflare builds with cloudless.gr',
  'Edge security done right: WAF, DDoS, and Zero Trust for small teams',
  'Greek SMEs going digital: cloud that just works, without the jargon',
  'EU data residency and GDPR-friendly hosting on the edge',
  'Migrating from AWS to Cloudflare: what teams actually save',
  'D1, KV, and Queues: edge data without a database ops team',
  'AI at the edge: Workers AI for real products, not demos',
  'Backups, monitoring, and uptime — the boring work cloudless.gr automates',
  'Faster sites, happier users: performance wins on Cloudflare Pages',
  'Why agencies charge months for what a fixed-scope build ships in weeks',
  'The real monthly cost of self-hosting vs managed cloud for a startup',
  'Static-first architecture: when you do not need a server at all',
  'Bot protection and Turnstile: stopping abuse before it costs you',
  'Hybrid done right: self-hosted NAS behind a Cloudflare tunnel',
  'Observability on a budget: logs and analytics without the SaaS tax',
  'Cron, queues, and scheduled jobs at the edge — automation that ships',
  'E-commerce on Cloudflare: fast checkouts, low infra spend',
];

const STOP = new Set(('the a an and or for to in on with of your you we our it is are be at by as that this from without not do does can'.split(' ')));
function tokset(s) {
  return new Set(String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/).filter(w => w.length > 2 && !STOP.has(w)));
}
// containment of the topic's tokens inside a post's token set
function overlap(tset, pset) {
  if (!tset.size) return 0;
  let hit = 0;
  for (const t of tset) if (pset.has(t)) hit++;
  return hit / tset.size;
}

const recentSets = posts
  .map(p => tokset(p.content_text || p.content || ''))
  .filter(s => s.size);

// Explicit override (webhook/env) always wins.
if (cfg.topic_override) {
  return [{ json: { ...cfg, access_token, topic: cfg.topic_override, topic_source: 'override' } }];
}

const dayBucket = Math.floor(Date.now() / 86400000);
const start = dayBucket % topics.length;
let chosen = null, best = null, bestScore = Infinity;
for (let i = 0; i < topics.length; i++) {
  const idx = (start + i) % topics.length;
  const t = topics[idx];
  const score = Math.max(0, ...recentSets.map(r => overlap(tokset(t), r)));
  if (score < bestScore) { bestScore = score; best = t; }
  if (score <= 0.3) { chosen = t; break; }
}
return [{
  json: {
    ...cfg,
    topic: chosen || best,
    access_token,
    topic_source: chosen ? 'fresh' : 'least-similar-fallback',
    recent_posts_checked: recentSets.length,
    best_overlap_score: Number(bestScore.toFixed(3)),
  }
}];
